import {exposureScale,sampleDescription} from './solar-display.js';
import * as THREE from './vendor/three.module.js';
import {solarSettings,solarPosition,sampleSurfaces} from './solar.js';
export function createSolarUI({scene,renderer,mainLight,decorativeShadow,getModel,getState,saveSettings,getCamera,getDisplayModel}){
 const $=s=>document.querySelector(s),panel=$('#panel-solar');let settings=solarSettings(getState().solar),contextRoot=new THREE.Group(),pathRoot=new THREE.Group(),map=null,worker=null,result=null,scaleMode='results';const display={show:true,opacity:1,neutral:true},originalMaterials=new WeakMap(),originalBackground=scene.background.clone();let selected=null,pointerStart=null;
 scene.add(contextRoot,pathRoot);const sun=new THREE.DirectionalLight(0xfff0c4,3.3);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.bias=-.00015;sun.shadow.normalBias=.08;scene.add(sun,sun.target);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
 panel.innerHTML=`<p class="panel-intro">Sun, shadows & direct sunlight hours. Calculated on your device.</p><label class="solar-switch"><input id="solar-enabled" type="checkbox"> Show sun path and shadows</label><div class="solar-fields"><label>Latitude (°)<input data-solar="lat" type="number" min="-89" max="89" step=".0001"></label><label>Longitude (° east)<input data-solar="lon" type="number" min="-180" max="180" step=".0001"></label><label>UTC offset (hours)<input data-solar="utc" type="number" min="-12" max="14" step=".25"></label><label>North rotation (°)<input data-solar="north" type="number" min="-180" max="180" step="1"></label></div><p class="note">Default: Cairo, UTC+2. Set the actual UTC offset for your chosen date, including daylight saving. North 0° = plan +Y; positive rotates north toward +X.</p><label class="solar-field">Date<input data-solar="date" type="date"></label><label class="solar-field">Local clock time <output id="solar-clock"></output><input data-solar="hour" type="range" min="0" max="23.75" step=".25"></label><p id="solar-position" class="note"></p><details><summary>Neighbouring buildings</summary><p class="note">Opaque axis-aligned blocks, in plan metres. Comparison designs are excluded.</p><div id="solar-context"></div><button id="solar-add-context" class="button add">＋ Add context block</button></details><div class="section-label spaced">Daily sunlight study</div><label class="solar-field">Sample surfaces<select data-solar="target"><option value="ground">Ground around building</option><option value="roof">Upward surfaces / roofs</option><option value="facade">Façades / vertical surfaces</option></select></label><label class="solar-field">Ground half-width (m)<input data-solar="extent" type="number" min="50" max="500" step="10"></label><label class="solar-field">Time step<select data-solar="step"><option value="15">15 minutes — finer</option><option value="30">30 minutes</option><option value="60">60 minutes — faster</option></select></label><button id="solar-run" class="button dark">Calculate sunlight hours</button><button id="solar-cancel" class="button" hidden>Cancel</button><p id="solar-status" role="status" aria-live="polite" class="note">One selected day; 500 surface samples or a 25 × 25 ground grid.</p><div class="solar-results-tools"><label class="solar-field">Colour scale<select id="solar-scale"><option value="results">Actual result range — reveal differences</option><option value="daylight">0 to daylight hours — compare runs</option></select></label><label class="solar-switch"><input id="solar-show-model" type="checkbox" checked> Show building</label><label class="solar-switch"><input id="solar-neutral" type="checkbox" checked> Neutral grey analysis view</label><label class="solar-field">Building opacity<input id="solar-opacity" type="range" min="0.1" max="1" step="0.1" value="1"></label><p id="solar-statistics" class="note"></p><p id="solar-selected" role="status" aria-live="polite" class="sample-readout">Run an analysis, then click or tap a coloured point.</p></div><button id="solar-csv" class="button add" disabled>Export sunlight CSV</button><p class="note">Geometric direct-sun exposure only. Opaque model; no clouds, diffuse sky, reflections, glazing transmission, weather or energy prediction. Sampling and approximate sun positions affect results. <a href="https://gml.noaa.gov/grad/solcalc/solareqns.PDF" target="_blank" rel="noopener">Solar method: NOAA</a>.</p>`;
 const clearRoot=root=>{for(const o of [...root.children]){o.traverse(n=>{n.geometry?.dispose();n.material?.dispose();});root.remove(o);}};
 function clearAnalysis(message='Settings changed. Recalculate sunlight hours.'){worker?.terminate();worker=null;if(map){scene.remove(map);map.geometry.dispose();map.material.dispose();map=null;}result=null;selected=null;$('#solar-statistics').textContent='';$('#solar-selected').textContent='Run an analysis, then click or tap a coloured point.';applyPresentation();$('#solar-cancel').hidden=true;$('#solar-run').disabled=false;$('#solar-csv').disabled=true;$('#solar-legend').hidden=true;$('#solar-status').textContent=message;}
 function applyPresentation(){const root=getDisplayModel();if(root){root.visible=display.show;root.traverse(o=>{if(!o.material)return;for(const m of (Array.isArray(o.material)?o.material:[o.material])){if(!originalMaterials.has(m))originalMaterials.set(m,{color:m.color?.clone(),opacity:m.opacity,transparent:m.transparent,depthWrite:m.depthWrite});const old=originalMaterials.get(m);if(m.color&&old.color)m.color.copy(result&&display.neutral?new THREE.Color(o.isMesh?0xb9b9b5:0x858582):old.color);m.opacity=old.opacity*display.opacity;m.transparent=old.transparent||display.opacity<1;m.depthWrite=old.depthWrite&&display.opacity===1;m.needsUpdate=true;}});}scene.background.copy(result&&display.neutral?new THREE.Color(0xf0f0ed):originalBackground);}
 function recolor(){if(!result||!map)return;const scale=exposureScale(result.values,result.daylight,scaleMode),colors=map.geometry.attributes.color;result.values.forEach((v,i)=>{const c=new THREE.Color().setHSL(.66*(1-scale.ratio(v)),.85,.5);colors.setXYZ(i,c.r,c.g,c.b);});colors.needsUpdate=true;const ticks=Array.from({length:5},(_,i)=>(scale.low+(scale.high-scale.low)*i/4).toFixed(2));const legend=$('#solar-legend');legend.hidden=false;legend.innerHTML=`<b>Direct sunlight hours · ${result.settings.date}</b><div class="solar-colour-bar" style="${scale.uniform&&scaleMode==='results'?'background:#24e813':''}"></div><div class="solar-ticks">${ticks.map(t=>`<span>${t}</span>`).join('')}</div><small>${scale.uniform?'All samples have the same calculated value.':scaleMode==='results'?'Actual range — colours are relative to this run.':'Fixed scale: 0 to sampled daylight hours.'}</small><div id="solar-point-value" class="sample-readout"></div>`;$('#solar-point-value').textContent=selected===null?'Tap a coloured point for its value.':sampleDescription(selected,result.samples[selected],result.values[selected]);$('#solar-statistics').textContent=`Minimum ${scale.min.toFixed(2)} h · maximum ${scale.max.toFixed(2)} h · mean ${scale.mean.toFixed(2)} h. Spread ${(scale.max-scale.min).toFixed(2)} h.${scale.uniform?' Uniform results at this time/sample resolution.':' Narrow ranges can produce strong colour contrast; read the numbers.'}`;applyPresentation();}
 $('#solar-scale').onchange=e=>{scaleMode=e.target.value;recolor();};$('#solar-show-model').onchange=e=>{display.show=e.target.checked;applyPresentation();};$('#solar-neutral').onchange=e=>{display.neutral=e.target.checked;applyPresentation();};$('#solar-opacity').oninput=e=>{display.opacity=+e.target.value;applyPresentation();};
 renderer.domElement.addEventListener('pointerdown',e=>{pointerStart=[e.clientX,e.clientY];});renderer.domElement.addEventListener('pointerup',e=>{
  if(!result||!map||!pointerStart||Math.hypot(e.clientX-pointerStart[0],e.clientY-pointerStart[1])>6)return;
  const rect=renderer.domElement.getBoundingClientRect(),camera=getCamera(),ray=new THREE.Raycaster(),pointer=new THREE.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1);camera.updateMatrixWorld();ray.setFromCamera(pointer,camera);ray.params.Points.threshold=map.material.size*.65;map.updateMatrixWorld(true);
  const hits=ray.intersectObject(map),root=getDisplayModel();let hit;for(const h of hits){const p=new THREE.Vector3().fromBufferAttribute(map.geometry.attributes.position,h.index).project(camera),px=(p.x+1)*rect.width/2+rect.left,py=(1-p.y)*rect.height/2+rect.top;if(Math.hypot(px-e.clientX,py-e.clientY)>14)continue;if(root?.visible&&display.opacity===1){const centre=new THREE.Vector3().fromBufferAttribute(map.geometry.attributes.position,h.index),r=new THREE.Raycaster(camera.position,centre.clone().sub(camera.position).normalize());if(!camera.isPerspectiveCamera){r.setFromCamera(new THREE.Vector2(p.x,p.y),camera);}const block=r.intersectObject(root,true)[0];if(block&&block.distance<r.ray.origin.distanceTo(centre)-.15)continue;}hit=h;break;}
  if(!hit)return;selected=hit.index;const text=sampleDescription(selected,result.samples[selected],result.values[selected]);$('#solar-selected').textContent=text;$('#solar-point-value').textContent=text;$('#solar-status').textContent=text.replace('\n',' · ');
 });
 function fields(){panel.querySelectorAll('[data-solar]').forEach(el=>el.value=settings[el.dataset.solar]);$('#solar-enabled').checked=settings.enabled;$('#solar-clock').textContent=String(Math.floor(settings.hour)).padStart(2,'0')+':'+String(Math.round(settings.hour%1*60)).padStart(2,'0');}
 function contextFields(){const list=$('#solar-context');list.innerHTML=settings.context.map((b,i)=>`<div class="context-block"><b>Block ${i+1}</b><button data-remove-context="${i}" aria-label="Remove block ${i+1}">×</button><div class="solar-fields">${Object.entries(b).map(([k,v])=>`<label>${k}<input type="number" data-block="${i}" data-property="${k}" value="${v}" min="${k==='x'||k==='y'?-500:1}" max="500"></label>`).join('')}</div></div>`).join('');list.querySelectorAll('[data-block]').forEach(el=>el.onchange=()=>{if(!Number.isFinite(el.valueAsNumber))return;settings.context[+el.dataset.block][el.dataset.property]=el.valueAsNumber;commit();contextFields();});list.querySelectorAll('[data-remove-context]').forEach(el=>el.onclick=()=>{settings.context.splice(+el.dataset.removeContext,1);commit();contextFields();});$('#solar-add-context').disabled=settings.context.length>=5;}
 function update(){clearRoot(contextRoot);for(const b of settings.context){const mesh=new THREE.Mesh(new THREE.BoxGeometry(b.width,b.height,b.depth),new THREE.MeshStandardMaterial({color:0xb7b9b2,roughness:.9}));mesh.position.set(b.x,b.height/2,b.y);mesh.castShadow=true;mesh.receiveShadow=true;contextRoot.add(mesh);}contextRoot.visible=settings.enabled;
  clearRoot(pathRoot);const p=solarPosition(settings.date,settings.hour,settings.lat,settings.lon,settings.utc,settings.north),height=getState().floors*getState().storey+(getState().podium?getState().podiumFloors*getState().storey:0),radius=Math.max(height*1.1,settings.extent),origin=new THREE.Vector3(0,height*.35,0);
  sun.visible=settings.enabled&&p.altitude>0;sun.target.position.copy(origin);sun.position.copy(origin).add(new THREE.Vector3(...p.direction).multiplyScalar(radius*4));const extent=Math.max(radius,...settings.context.map(b=>Math.max(Math.abs(b.x)+b.width,Math.abs(b.y)+b.depth,b.height)));Object.assign(sun.shadow.camera,{left:-extent,right:extent,top:extent,bottom:-extent,near:1,far:radius*8+extent*4});sun.shadow.camera.updateProjectionMatrix();
  $('.compass').hidden=settings.enabled;mainLight.visible=!settings.enabled;decorativeShadow.visible=!settings.enabled;pathRoot.visible=settings.enabled;
  const pts=[];for(let h=0;h<=24;h+=.125){const q=solarPosition(settings.date,h,settings.lat,settings.lon,settings.utc,settings.north);if(q.altitude>0)pts.push(origin.clone().add(new THREE.Vector3(...q.direction).multiplyScalar(radius)));}if(pts.length>1)pathRoot.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),new THREE.LineBasicMaterial({color:0xbc8731})));if(p.altitude>0){const orb=new THREE.Mesh(new THREE.SphereGeometry(radius*.025,12,8),new THREE.MeshBasicMaterial({color:0xffbb42}));orb.position.copy(origin).add(new THREE.Vector3(...p.direction).multiplyScalar(radius));pathRoot.add(orb);}
  const n=settings.north*Math.PI/180,arrow=new THREE.ArrowHelper(new THREE.Vector3(Math.sin(n),0,Math.cos(n)),new THREE.Vector3(0,.5,0),radius*.4,0x32666c);pathRoot.add(arrow);
  $('#solar-position').textContent=`Sun altitude ${p.altitude.toFixed(1)}° · azimuth ${p.azimuth.toFixed(1)}° from north${p.altitude<=0?' · Sun below horizon':''}`;fields();
 }
 function commit(){settings=solarSettings(settings);saveSettings(structuredClone(settings));clearAnalysis();update();}
 panel.querySelectorAll('[data-solar]').forEach(el=>{const change=()=>{if(el.type==='number'&&!Number.isFinite(el.valueAsNumber))return;settings[el.dataset.solar]=el.type==='date'||el.tagName==='SELECT'?el.value:+el.value;commit();};el.addEventListener(el.type==='range'?'input':'change',change);});$('#solar-enabled').onchange=e=>{settings.enabled=e.target.checked;commit();};$('#solar-add-context').onclick=()=>{settings.context.push({x:70+settings.context.length*40,y:0,width:30,depth:30,height:60});commit();contextFields();};$('#solar-cancel').onclick=()=>clearAnalysis('Analysis cancelled.');
 function triangles(root){root.updateMatrixWorld(true);const out=[];root.traverse(o=>{if(!o.isMesh)return;const p=o.geometry.attributes.position,index=o.geometry.index,v=new THREE.Vector3();for(let i=0;i<(index?index.count:p.count);i++){v.fromBufferAttribute(p,index?index.getX(i):i).applyMatrix4(o.matrixWorld);out.push(v.x,v.y,v.z);}});return out;}
 $('#solar-run').onclick=()=>{clearAnalysis('Preparing geometry…');settings.enabled=true;saveSettings(structuredClone(settings));update();let model;try{model=getModel();const own=triangles(model),all=new Float64Array([...own,...triangles(contextRoot)]);model.traverse(o=>{o.geometry?.dispose();if(o.material)o.material.dispose();});model=null;let samples;if(settings.target==='ground'){samples=[];for(let x=0;x<25;x++)for(let z=0;z<25;z++)samples.push({position:[-settings.extent+(x+.5)*settings.extent*2/25,.04,-settings.extent+(z+.5)*settings.extent*2/25],normal:[0,1,0]});}else samples=sampleSurfaces(own,settings.target);if(!samples.length){$('#solar-status').textContent='No eligible surfaces remain. Change the target or model.';return;}worker=new Worker(new URL('./solar-worker.js',import.meta.url),{type:'module'});$('#solar-run').disabled=true;$('#solar-cancel').hidden=false;const snapshot=structuredClone(settings);const job=worker;worker.onmessage=({data})=>{if(worker!==job)return;if(data.error){clearAnalysis('Analysis failed: '+data.error);return;}if(data.progress!==undefined){$('#solar-status').textContent='Calculating… '+Math.round(data.progress*100)+'%';return;}if(!data.values)return;worker.terminate();worker=null;$('#solar-run').disabled=false;$('#solar-cancel').hidden=true;result={samples,values:data.values,settings:snapshot,daylight:data.daylight,project:structuredClone(getState())};const pos=[],colors=[],max=Math.max(data.daylight,.1);samples.forEach((s,i)=>{pos.push(...s.position.map((v,k)=>v+s.normal[k]*.07));const c=new THREE.Color().setHSL(.66*(1-data.values[i]/max),.85,.5);colors.push(c.r,c.g,c.b);});const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));map=new THREE.Points(g,new THREE.PointsMaterial({size:settings.target==='ground'?settings.extent*2/25*.8:2.5,vertexColors:true,sizeAttenuation:true,depthTest:true}));scene.add(map);$('#solar-status').textContent=`${samples.length} samples · ${data.daylight.toFixed(2)} h sampled daylight · exposure ${Math.min(...data.values).toFixed(2)}–${Math.max(...data.values).toFixed(2)} h`;recolor();$('#solar-selected').textContent='Click or tap a coloured point to read its direct-sun hours and coordinates.';$('#solar-csv').disabled=false;};worker.onerror=e=>{if(worker===job)clearAnalysis('Analysis failed: '+e.message);};worker.postMessage({triangles:all,samples,settings:snapshot},[all.buffer]);}catch(e){clearAnalysis('Analysis failed: '+e.message);}};
 $('#solar-csv').onclick=()=>{if(!result)return;const r=result,rows=[['FORM direct sunlight hours — geometric estimate'],['date',r.settings.date],['latitude',r.settings.lat],['longitude',r.settings.lon],['UTC offset',r.settings.utc],['north rotation',r.settings.north],['time step minutes',r.settings.step],['target',r.settings.target],['sampled daylight hours',r.daylight],['context blocks JSON',JSON.stringify(r.settings.context)],['project JSON',JSON.stringify(r.project)],['x_m','height_m','plan_y_m','normal_x','normal_up','normal_plan_y','direct_sun_hours'],...r.samples.map((s,i)=>[...s.position,...s.normal,r.values[i]])],csv=rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='form-sunlight-'+r.settings.date+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);};
 fields();contextFields();update();return{refresh(){clearAnalysis('Model changed. Recalculate sunlight hours.');update();},load(raw){settings=solarSettings(raw);clearAnalysis();fields();contextFields();update();}};
}
